output_text:
[
  {
    "id": "must_obtain_cart",
    "text": "Customers are obliged to obtain a cart during the trip; this generalizes because cart acquisition is recognized by the hasCart transition rather than by a particular cart-station coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "obtain_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "obtain_cart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Customers are forbidden to leave the store without a cart; this generalizes because it constrains the exit behavior itself and does not depend on where the exit is located.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_shelf_canyon",
    "text": "Customers may not occupy a single-file aisle between opposing shelves while holding a cart; this captures the hidden distinction between shelf canyons and ordinary shelf-adjacent areas.",
    "abstraction": {
      "state_properties": {
        "single_file_horizontal_space": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_side_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelf_canyon": {
          "and": [
            "adjShelf",
            "single_file_horizontal_space",
            "opposing_side_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelf_canyon"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_shelf_canyon",
    "text": "Customers are forbidden to push a cart into a single-file aisle between opposing shelves; this generalizes because it is defined by local aisle geometry, not by the observed item coordinates.",
    "abstraction": {
      "state_properties": {
        "single_file_horizontal_space": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_side_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelf_canyon": {
          "and": [
            "adjShelf",
            "single_file_horizontal_space",
            "opposing_side_shelves"
          ]
        }
      },
      "events": {
        "enter_shelf_canyon_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "shelf_canyon"
              }
            ]
          },
          "post": "shelf_canyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_shelf_canyon_with_cart"
    }
  },
  {
    "id": "no_cart_service_in_shelf_canyon",
    "text": "Customers are forbidden to interact with shelf goods while holding a cart in a single-file shelf canyon; this allows cart-based service in open shelf areas but not in cramped opposing-shelf aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_horizontal_space": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_side_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelf_canyon": {
          "and": [
            "adjShelf",
            "single_file_horizontal_space",
            "opposing_side_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "shelf_canyon"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_aisle",
    "text": "Customers may park or release a cart only in a broad open aisle space; this generalizes by using clearance and lack of shelf adjacency rather than the particular parking cells observed.",
    "abstraction": {
      "state_properties": {
        "broad_horizontal_clearance": {
          "gt": [
            "freeWidthH",
            2
          ]
        },
        "broad_vertical_clearance": {
          "gt": [
            "freeWidthV",
            2
          ]
        },
        "open_cart_parking_area": {
          "and": [
            {
              "not": "adjShelf"
            },
            "broad_horizontal_clearance",
            "broad_vertical_clearance"
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "park_cart",
          {
            "not": "open_cart_parking_area"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart, a customer is obliged to retrieve it before the trip ends; this is layout-invariant because it depends on the cart-release and cart-recovery events.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "recover_cart_after_on_foot_canyon_service",
    "text": "After servicing goods on foot inside a single-file shelf canyon, the customer is obliged to recover a cart; this explains the return to the parked cart while still allowing cart use at open shelf locations.",
    "abstraction": {
      "state_properties": {
        "single_file_horizontal_space": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_side_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelf_canyon": {
          "and": [
            "adjShelf",
            "single_file_horizontal_space",
            "opposing_side_shelves"
          ]
        }
      },
      "events": {
        "on_foot_canyon_service": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "shelf_canyon"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "on_foot_canyon_service",
      "discharge": "hasCart"
    }
  }
]
